import hashlib, json, os, shutil, subprocess, sys, tempfile
from concurrent.futures import ThreadPoolExecutor
from fractions import Fraction as Fr
from pathlib import Path
import pytest
import sympy as sp

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "code" / "classical"))
sys.path.insert(0, str(ROOT / "code" / "p5_entry"))
import conventions as C  # noqa: E402
import p14_conventions as PC  # noqa: E402
import jetpoly as J  # noqa: E402
import certio  # noqa: E402

CERT = ROOT / "certificates"


def cj(name, root=ROOT):
    return json.loads((root / "certificates" / name).read_text())


# ---------------------------------------------------------------- unit / deterministic
def test_C3_boundary_identity_generic_and_conformal():
    import boundary_identity as BI
    g = BI.generic_jet_proof(+1)
    assert g["identically_zero"] and g["residual_terms"] == 0
    bad = BI.generic_jet_proof(-1)
    assert not bad["identically_zero"] and bad["residual_terms"] > 0
    cc = BI.conformal_control(+1)
    assert cc["residual_zero"] and cc["nontrivial"]
    assert not BI.conformal_control(-1)["residual_zero"]


