def test_multidegree_lemma_corrected():
    """E_u P_d = P_{d-e_u} E_u on a mixed polynomial (h,c multidegree)."""
    h = J.var("h", (0, 1)); hd = J.var("h", (0, 1), (2,)); c = J.var("c", 0, (1,)); c0 = J.var("c", 0)
    F = J.add(J.mul(h, J.mul(hd, c)), J.mul(c0, hd), J.mul(J.mul(h, h), J.mul(hd, c0)), J.scale(J.mul(hd, hd), 3))

    def deg(m):
        dh = sum(1 for v in m if J.KEYS[v][0] == "h")
        return (dh, len(m) - dh)

    def P(p, d):
        return {m: k for m, k in p.items() if deg(m) == d}
    for d in [(1, 1), (3, 1), (2, 0), (2, 1)]:
        lhs = J.euler(P(F, d), "h", (0, 1))
        rhs = P(J.euler(F, "h", (0, 1)), (d[0] - 1, d[1]))
        assert lhs == rhs
    src = (ROOT / "code" / "classical" / "master_kappa2.py").read_text()
    assert "E_u P_d = P_{d - e_u} E_u" in src and "Euler operators commute with projection" not in src


