CONTRACT_RS = ROOT / "certificates" / "P14_release.json"


def test_release_accepted_and_hard_stops():
    r = json.loads(CONTRACT_RS.read_text())
    assert r["revision"] == PC.REVISION == "p14r"
    assert r["execution_pass"] and r["classical"]["classical_readiness_for_ch_identity"] and r["release_claim_accepted"]
    assert r["publication"] == "accepted" and (CERT / "P14_closure_release.json").exists()
    assert not (CERT / "P14_release_rejected.json").exists()
    assert not (CERT / "P13_release.json").exists() and not (CERT / "P13_closure_release.json").exists()
    assert "pass" not in r
    hs = r["hard_stops"]
    assert hs["quantum_inputs_evaluated"] == "not_earned" and hs["D02_quantum_evaluated"] is False
    assert hs["D12_quantum_evaluated"] is False and hs["D12_status"] == "Missing" and hs["symmetry_restored"] is False
    assert hs["O1_closure"] == "NOT_CLOSED" and hs["XV_B_opened"] is False and hs["Route_B_discharged"] is False
    assert hs["loop_evaluations_performed"] is False and hs["u_R_c_delta_added"] is False
    assert r["insertion_status"].startswith("Frozen")


