# ---------------------------------------------------------------- end-to-end mutations
STAGES = {"gauge": "code/classical/gauge_fixing_map.py", "master": "code/classical/master_kappa2.py",
          "ch": "code/p4_classical/ch_source_audit.py", "release": "code/p5_entry/release_p14.py"}


def _frozen_input_tops():
    """top-level directories holding the frozen P.3/P.4 inputs (the freeze list) -- the isolated copies must contain
    all of them, otherwise every copy is 'unfrozen' and P.5 mutations would be rejected for the wrong reason."""
    L = json.loads((ROOT / PC.P13_FROZEN_LIST).read_text())
    return sorted({f["path"].split("/")[0] for f in L["files"]})


COPY_SUBS = tuple(sorted(set(("code", "certificates", "exports", "ledgers", "tools", "provenance", "reproducibility",
                              "archival", "notes", "tests")) | set(_frozen_input_tops())))


def _copy_pkg():
    d = Path(tempfile.mkdtemp(prefix="p14e2e_"))
    for sub in COPY_SUBS:
        if (ROOT / sub).exists():
            shutil.copytree(ROOT / sub, d / sub, ignore=shutil.ignore_patterns("__pycache__"))
    shutil.copy(ROOT / "RELEASE_STATUS.json", d / "RELEASE_STATUS.json")
    return d


def _run(d, stage, env_mut=""):
    env = dict(os.environ, P13_MUTATIONS=env_mut, P14_MUTATIONS="")
    p = subprocess.run([sys.executable, str(d / STAGES[stage])], cwd=d, env=env, capture_output=True, text=True,
                       timeout=3600)
    return p.returncode


def _corrupt_export(d):
    f = d / "exports" / "ell4_generating_polynomial.srepr"
    e = sp.sympify(f.read_text().strip())
    t = sp.Add.make_args(e)[0]
    f.write_text(sp.srepr(sp.expand(e + sp.Rational(2, 5) * t)) + "\n")


def _stale_hash(d):
    f = d / "certificates" / "P13_quartic_verified.json"
    q = json.loads(f.read_text())
    q["ell4_sha256"] = hashlib.sha256(b"stale-p10-ell4").hexdigest()
    f.write_text(json.dumps(q, indent=2) + "\n")


CASES = {
    "flipped_odd_sign": {"env": "flip_odd_derivative_sign", "stages": ["master"], "flag": "required_classical_BV_components_verified"},
    "corrupted_ell4_coefficient": {"pre": _corrupt_export, "stages": ["master"], "flag": "required_classical_BV_components_verified"},
    "dropped_hstar_c_row": {"env": "drop_hstar_c_row", "stages": ["ch"], "flag": "ch_dependency_inventory_complete"},
    "altered_gauge_shift": {"env": "alter_gf_shift", "stages": ["gauge", "master"], "flag": "gauge_fixing_map_constructed"},
    "omitted_cstar_term": {"env": "drop_cstar", "stages": ["master"], "flag": "required_classical_BV_components_verified"},
    "stale_hash": {"pre": _stale_hash, "stages": ["master"], "flag": "required_classical_BV_components_verified"},
}


def _chain(name):
    case = CASES[name]
    d = _copy_pkg()
    assert (d / "certificates" / "P14_closure_release.json").exists()   # stale closure artifact present before
    if "pre" in case:
        case["pre"](d)
    codes = {s: _run(d, s, case.get("env", "")) for s in case["stages"]}
    codes["release"] = _run(d, "release")
    out = {"dir": str(d), "codes": codes,
           "master": cj("P13_master_kappa2.json", d), "gauge": cj("P13_gauge_fixing_map.json", d),
           "ch": cj("P13_ch_source_audit.json", d),
           "status": json.loads((d / "RELEASE_STATUS.json").read_text()),
           "closure_exists": (d / "certificates" / "P14_closure_release.json").exists(),
           "release_exists": (d / "certificates" / "P14_release.json").exists(),
           "rejected": json.loads((d / "certificates" / "P14_release_rejected.json").read_text())
           if (d / "certificates" / "P14_release_rejected.json").exists() else None}
    return name, out


@pytest.fixture(scope="module")
def e2e():
    with ThreadPoolExecutor(max_workers=6) as ex:
        res = dict(ex.map(_chain, list(CASES)))
    summary = {k: {"stage_codes": v["codes"], "flag": CASES[k]["flag"],
                   "flag_value": v["status"]["classical"]["flags"][CASES[k]["flag"]],
                   "readiness": v["status"]["classical"]["classical_readiness_for_ch_identity"],
                   "P3_P4_frozen_as_P5_inputs": v["status"]["P3_P4_frozen_as_P5_inputs"],
                   "P5_entry_earned": v["status"]["P5_entry_earned"],
                   "release_claim_accepted": v["status"]["release_claim_accepted"],
                   "publication": v["status"]["publication"], "closure_artifact_exists": v["closure_exists"],
                   "master_residuals": v["master"]["required_master_residuals"][:6],
                   "failed_prerequisites": v["status"]["classical"]["failed_prerequisites"]} for k, v in res.items()}
    outd = ROOT / "build" / "p14" / "test_results"
    outd.mkdir(parents=True, exist_ok=True)
    (outd / "e2e_mutations.json").write_text(json.dumps(summary, indent=2, default=str) + "\n")
    yield res
    for v in res.values():
        shutil.rmtree(v["dir"], ignore_errors=True)


def _assert_rejected(r, flag):
    assert r["codes"]["release"] != 0
    st = r["status"]
    assert st["classical"]["flags"][flag] is False
    assert st["classical"]["classical_readiness_for_ch_identity"] is False
    assert st["P3_P4_frozen_as_P5_inputs"] is False and st["P5_entry_earned"] is False   # frozen values changed
    assert st["release_claim_accepted"] is False and st["publication"] == "REJECTED"
    assert not r["closure_exists"] and not r["release_exists"] and r["rejected"] is not None


