# ---------------------------------------------------------------- p12: residual-record invariants
def test_certio_rejects_inconsistent_record_before_serialization():
    good = {"kappa0": {"Q_terms": [0, 0, 0, 0], "Q_identically_zero": True}}
    certio.dumps(good)
    for counts, flag in (([0, 0, 120, 0], True), ([290, 0, 0, 0], True), ([0, 0, 0, 0], False)):
        bad = {"kappa1": {"Q_terms": counts, "Q_identically_zero": flag}}
        with pytest.raises(certio.CertificateInvariantError):
            certio.dumps(bad)
    assert "\n" not in certio.dumps({"Q_terms": [0, 0, 0, 0], "Q_identically_zero": True}).split("Q_terms")[1].split("]")[0]


def test_residual_records_regenerated_and_agree():
    q = cj("P13_quartic_verified.json")
    m = cj("P13_master_kappa2.json")
    qc7, mg = q["controls"]["C7_noether_exact"], m["details"]["grav_af0_deterministic"]
    for o in certio.ORDERS:
        assert qc7[o]["Q_terms"] == [0, 0, 0, 0] and qc7[o]["Q_identically_zero"] is True
        assert mg[o]["Q_terms"] == [0, 0, 0, 0] and mg[o]["Q_identically_zero"] is True
    cross = certio.cross_check(qc7, q["controls"]["C7_parameters"], mg, m["details"]["grav_af0_parameters"])
    assert cross["same_inputs"] and cross["agree"], cross
    for f in sorted(list((ROOT / "certificates").glob("P13_*.json")) + list((ROOT / "certificates").glob("P14_*.json"))):
        assert not certio.invariant_violations(json.loads(f.read_text())), f.name
    rs = json.loads(CONTRACT_RS.read_text())
    assert rs["classical"]["deterministic_prerequisites"]["cross_certificate_quartic_vs_master_agree"] is True
    assert rs["classical"]["deterministic_prerequisites"]["residual_record_invariants_all_certificates"] is True


