def test_dossier_detects_broken_link():
    """Mutation: a wrong expected value / missing function / missing certificate key makes the row unresolved."""
    import dossier as D
    D.T = "tests/test_p14.py"            # the frozen p13 dossier library, pointed at the active test file (as dossier_p14)
    cache = {}
    row = D.R("X", "x", D.F_MS, ["run"], [(D.MS, "/required_master_residuals", ["something"])], ["test_enumeration_lemma"])
    assert not D.resolve_row(row, cache)["resolved"]
    row = D.R("X", "x", D.F_MS, ["no_such_function"], [(D.MS, "/required_master_residuals", [])], ["test_enumeration_lemma"])
    assert not D.resolve_row(row, cache)["resolved"]
    row = D.R("X", "x", D.F_MS, ["run"], [(D.MS, "/no/such/key", True)], ["test_enumeration_lemma"])
    assert not D.resolve_row(row, cache)["resolved"]
    row = D.R("X", "x", D.F_MS, ["run"], [(D.MS, "/required_master_residuals", [])], ["test_no_such_test"])
    assert not D.resolve_row(row, cache)["resolved"]
    assert D.matches(1, 1) and not D.matches(True, 1) and not D.matches([0, 0, 1, 0], [0, 0, 0, 0])


