# ---------------------------------------------------------------- p12: gate enforcement for resumed builds
def _copy_full_pkg():
    d = Path(tempfile.mkdtemp(prefix="p14resume_"))
    for sub in ("code", "certificates", "exports", "ledgers", "tools", "manuscript", "build", "provenance",
                "reproducibility", "archival", "notes", "tests"):
        if (ROOT / sub).exists():
            shutil.copytree(ROOT / sub, d / sub, ignore=shutil.ignore_patterns("__pycache__", "test_results"))
    for f in ("README.md", "RELEASE_STATUS.json", "REBUILD_INSTRUCTIONS.md"):
        if (ROOT / f).exists():
            shutil.copy(ROOT / f, d / f)
    (d / "dist").mkdir(exist_ok=True)
    for st in ("XVI-P-science", "XVI-P-appendix", "XVI-P"):           # pre-existing artifacts that must not survive
        (d / "manuscript" / f"{st}.pdf").write_bytes(b"%PDF-1.5 placeholder (pre-existing artifact)\n")
    for z in ("XVI-P-review-focus.zip", "XVI-P-full.zip", "XVI-P-p23-source-only.zip"):
        (d / "dist" / z).write_bytes(b"PK placeholder (pre-existing artifact)")
    (d / "RELEASE_MANIFEST_EXTERNAL.txt").write_text("pre-existing manifest\n")
    return d


RESUME = {"pdf": _mut_master_count, "zip": _stale_hash, "manifest": _mut_quartic_count, "manifest_unverified_pdfs": None}


def _resume_chain(name):
    d = _copy_full_pkg()
    sync = Path(tempfile.mkdtemp(prefix="p14sync_"))
    if RESUME[name] is not None:
        RESUME[name](d)
    stage = name.split("_")[0]
    env = dict(os.environ, P14_SYNC_DIR=str(sync), P13_MUTATIONS="", P14_MUTATIONS="")
    p = subprocess.run([sys.executable, str(d / "tools" / "build.py"), "--from-stage", stage, "--skip-tests"],
                       cwd=d, env=env, capture_output=True, text=True, timeout=1800)
    out = {"rc": p.returncode, "stage": stage,
           "pdfs_left": [x.name for x in (d / "manuscript").glob("*.pdf")],
           "zips_left": [x.name for x in (d / "dist").glob("*.zip")],
           "manifest_left": (d / "RELEASE_MANIFEST_EXTERNAL.txt").exists(),
           "stale": sorted(x.name for x in (d / "stale").glob("*")) if (d / "stale").exists() else [],
           "marker": (d / "PUBLICATION_REJECTED.txt").exists(),
           "synced": sorted(x.name for x in sync.iterdir()),
           "reasons": json.loads((d / "stale" / "REJECTED.json").read_text())["reasons"][:6]
           if (d / "stale" / "REJECTED.json").exists() else None}
    shutil.rmtree(d, ignore_errors=True)
    shutil.rmtree(sync, ignore_errors=True)
    return name, out


@pytest.fixture(scope="module")
def resumed():
    with ThreadPoolExecutor(max_workers=4) as ex:
        res = dict(ex.map(_resume_chain, list(RESUME)))
