def test_freeze_binding():
    import freeze_p13 as FZ
    sys.path.insert(0, str(ROOT / "tools"))
    import source_manifest as SM
    fr = FZ.freeze(ROOT)
    assert fr["P3_P4_frozen_as_P5_inputs"] is True and fr["frozen_code_unchanged"] and fr["frozen_values_unchanged"]
    assert fr["F1"]["bound_to_p13_tree"] and fr["F1"]["bound_to_p13_zip"] and fr["F1"]["mismatches"] == 0
    assert fr["F1"]["independent_comparisons"] == 77
    assert fr["F2"]["files"] == 54 and fr["F2"]["changed_or_missing"] == [] and fr["F3"]["differences"] == []
    rs = _rs()
    p13 = rs["p13_independent_rebuild"]
    assert p13["independent_rebuild_passed"] is True and p13["bound_to_source_tree_sha256"] == PC.P13_SOURCE_TREE_SHA256
    assert p13["bound_to_source_zip_sha256"] == PC.P13_SOURCE_ZIP_SHA256 and "SAME box" in p13["caveat"]
    # NOT inherited: the p14 tree differs from the p13 tree, and the p14 independent flag is separate
    assert SM.tree_sha(ROOT) != PC.P13_SOURCE_TREE_SHA256
    # p15: the contract record's flag reads the p14r report path, which (where present) is bound to the p14r tree, so
    # it is never true for this tree; the CURRENT-tree flag is the p15 status flag (pending)
    assert rs["independent_rebuild_passed"] in ("pending", False)
    assert json.loads((ROOT / "RELEASE_STATUS.json").read_text())["independent_rebuild_passed"] == "pending"
    # the reviewer's files are untouched where present (never written by this package)
    live = ROOT / "reproducibility" / "independent_rebuild_report.json"
    if live.exists():
        assert hashlib.sha256(live.read_bytes()).hexdigest() == PC.P13_INDEPENDENT_REPORT_SHA256
    ref = ROOT / "reproducibility" / "reference_values.json"
    if ref.exists():
        assert hashlib.sha256(ref.read_bytes()).hexdigest() == PC.P13_REFERENCE_VALUES_SHA256


def _flip(rel, path, value):
    def f(d):
        p = d / rel
        o = json.loads(p.read_text())
        cur = o
        for k in path[:-1]:
            cur = cur[k]
        cur[path[-1]] = value
        p.write_text(json.dumps(o, indent=1))
    return f


def _append(rel, text):
    def f(d):
        with open(d / rel, "a") as fh:
            fh.write(text)
    return f


GATE_MUTS = {
    "baseline_unmutated": lambda d: None,
    "dred_mutation_not_rejected": _flip("certificates/P14_dred_rules.json", ["mutations", "premature_d4", "rejected"], False),
    "counterterm_flag_false": _flip("certificates/P14_counterterm_domain.json", ["counterterm_domain_defined"], False),
    "D11_matching_verified_true": _flip("certificates/P14_prescription_D11_matching.json", ["D11_matching_verified"], True),
    "D12_value_zero": _flip("certificates/P14_amplitude_rules.json", ["graphs", "D12", "value"], 0),
    "amplitude_mutation_not_rejected": _flip("certificates/P14_amplitude_rules.json",
                                             ["mutations", "wrong_ghost_loop_sign", "rejected"], False),
    "frozen_classical_file_changed": _append("code/classical/conventions.py", "\n# p14 edit (must break the freeze)\n"),
    "p13_independent_report_tampered": _flip("archival/p13/reproducibility/independent_rebuild_report_p13.json",
                                             ["pass"], False),
}


def _gate_chain(name):
    d = _copy_pkg()
    live = d / "reproducibility" / "independent_rebuild_report.json"
    if name == "p13_independent_report_tampered" and live.exists():
        live.unlink()          # the archived copy is authoritative; keep the live copy out of this mutation
    GATE_MUTS[name](d)
    rc = _run(d, "release")
    st = json.loads((d / "RELEASE_STATUS.json").read_text())
    out = {"rc": rc, "status": st, "closure_exists": (d / "certificates" / "P14_closure_release.json").exists(),
           "rejected_exists": (d / "certificates" / "P14_release_rejected.json").exists()}
    shutil.rmtree(d, ignore_errors=True)
    return name, out


