def test_dred_premature_d4_changes_finite_part_and_is_caught():
    import dred as DR
    a, b = DR.A_, DR.B_
    good = DR.toy_four_d_part()
    assert sp.simplify(good["finite"] - (b / 4 + a / 8)) == 0
    # the premature-d=4 result would silently drop a/8 ...
    bad = DR.toy_four_d_part(mutation="premature_d4", enforce=False)
    assert sp.simplify(bad["finite"] - b / 4) == 0 and sp.simplify(good["finite"] - bad["finite"]) != 0
    # ... and the guarded pipeline refuses it
    with pytest.raises(DR.PrematureD4Substitution):
        DR.toy_four_d_part(mutation="premature_d4")


def test_dred_evanescent_trace_is_d_minus_4_times_pole():
    import dred as DR
    t2 = DR.toy_evanescent_trace()
    assert sp.simplify(t2["finite"] + DR.A_ / 2) == 0 and sp.simplify(t2["pole"]) == 0
    with pytest.raises(DR.UncontractedObjects):
        DR.toy_evanescent_trace(mutation="contract_after_laurent")


def test_dred_trace_ghat_eq_4_rejected():
    import dred as DR
    bad = DR.Rules(trace_hat=4)
    assert bad.check()["pass"] is False
    assert DR.Rules().check()["pass"] is True
    # p15 contract correction (finding F1/F2 of the p14r independent rebuild): a numeric trace is refused structurally
    with pytest.raises(DR.NumericTraceForbidden):
        DR.toy_evanescent_trace(rules=bad)
    # display only: with tr ghat = 4 the evanescent trace vanishes identically: the (d-4) x pole finite part is lost
    t2 = DR.toy_evanescent_trace(rules=DR.Rules(trace_hat=4, display_only=True), enforce=False)
    assert sp.simplify(t2["finite"]) == 0 != sp.simplify(DR.toy_evanescent_trace()["finite"])


def test_dred_known_reductions_and_contraction_engine():
    import dred as DR
    kr = DR.known_reductions(DR.Rules())
    assert kr["pass"] and all(kr.values())
    # eta^{rs} ghat_rs = d after the Gt trace rule (contraction before expansion)
    tot = sum(DR.ETA[r] * (1 - DR.ETA[r] * DR.Gt(r, r)) * DR.ETA[r] for r in range(4))
    assert sp.simplify(DR.eta_trace_Gt(sp.expand(tot), DR.Rules()) - DR.d) == 0
    with pytest.raises(DR.UncontractedObjects):
        DR.eta_trace_Gt(DR.Gt(0, 1) + DR.Gt(0, 0), DR.Rules())


# ================================================================ p14r: independent Hessian-route regeneration (W6)
def test_hessian_route_regenerates_D01_D02_D03_D12():
    import hessian_route as HR, amplitude_rules as A
    ex = HR.compare_exports(ROOT)
    assert ex["all_agree"] is True
    for g, n in (("D01", 100), ("D02", 94), ("D03", 100), ("D12", 94)):
        assert ex[g]["agree"] and ex[g]["n_mismatches"] == 0 and ex[g]["components"] == n, g
        assert ex[g]["export_sha256"] == json.loads((ROOT / "exports" / "P14_integrands" / f"{g}.json").read_text())["sha256"]
    _, meta = HR.reference()
    assert all(meta["graviton_inverse"].values()) and all(meta["structural"].values())
    # the independent route rejects rule-level mutations of the graphs it covers
    for mname, g in (("wrong_tadpole_factor", "D02"), ("wrong_ghost_loop_sign", "D03"), ("offdiag_multiplicity", "D01")):
        w = HR.W6(A.build_integrands(A.apply_mutations(A.base_rules(), {mname})))
        assert w["checks"][f"{g}_hessian_route_equals_integrand"] is False, mname
